 "🟡 {0} Finance payment(s) due within {1} days — {2}": "🟡 {1} ရက်အတွင်း ပေးရန်ရှိသော ဘဏ္ဍာရေး ငွေပေးချေမှု {0} ခု — {2}",
 "🟡 Approaching the": "🟡 နီးကပ်လာပြီ —",
