 "1 day before": "1 ရက်အလို",
 "1 list will be saved.": "စာရင်း 1 ခု သိမ်းဆည်းပါမည်။",
 "1. Choose the menu (add more menus if needed) · 2. Enter how many pax to cook · 3. The ingredient list is worked out · 4. Items and quantities are grouped by supplier, ready to order.": "1. မီနူးကို ရွေးပါ (လိုအပ်ပါက မီနူးများ ထပ်ထည့်ပါ) · 2. ချက်ပြုတ်မည့် pax ကို ထည့်ပါ · 3. ပါဝင်ပစ္စည်းစာရင်းကို တွက်ချက်ပေးမည် · 4. ပစ္စည်းများနှင့် အရေအတွက်များကို ပေးသွင်းသူအလိုက် အုပ်စုဖွဲ့ပြီး မှာယူရန် အဆင်သင့်ဖြစ်မည်။",
 "1. Verify the outstanding balance": "1. ကျန်ငွေကို စစ်ဆေးပါ",
 "14 days before": "14 ရက်အလို",
 "2. Payment request": "2. ငွေပေးချေရန် တောင်းဆိုမှု",
 "3 days before": "3 ရက်အလို",
 "5 lowest-profit / loss-making events": "အမြတ်အနည်းဆုံး / ဆုံးရှုံးနေသော ပွဲ 5 ခု",
 "7 days before": "7 ရက်အလို",
 "A completed task is kept in the history and cannot be deleted. Cancel it instead if it was a mistake.": "ပြီးစီးပြီးသော လုပ်ငန်းကို မှတ်တမ်းတွင် သိမ်းထားသဖြင့် ဖျက်၍မရပါ။ အမှားဖြစ်ပါက ပယ်ဖျက်ပါ။",
 "A completed task is part of the history and cannot be edited. Reopen it first.": "ပြီးစီးပြီးသော လုပ်ငန်းသည် မှတ်တမ်း၏ အစိတ်အပိုင်းဖြစ်သဖြင့် ပြင်၍မရပါ။ အရင်ဆုံး ပြန်ဖွင့်ပါ။",
 "A cost with the same type, supplier, reference, amount and date already exists for this event. Save anyway only if it is a genuinely separate cost.": "ဤပွဲအတွက် အမျိုးအစား၊ ပေးသွင်းသူ၊ ကိုးကားနံပါတ်၊ ပမာဏနှင့် ရက်စွဲတူသော ကုန်ကျစရိတ်တစ်ခု ရှိပြီးသားဖြစ်သည်။ အမှန်တကယ် သီးခြားကုန်ကျစရိတ် ဖြစ်မှသာ ဆက်လက်သိမ်းပါ။",
 "A customer named \"{0}\" already exists for this company. Reject this one or change the name first.": "ဤကုမ္ပဏီအတွက် \"{0}\" အမည်ရှိ ဖောက်သည် ရှိပြီးဖြစ်သည်။ ဤတစ်ခုကို ပယ်ချပါ သို့မဟုတ် အမည်ကို အရင်ပြောင်းပါ။",
 "A decision is needed": "ဆုံးဖြတ်ချက် လိုအပ်နေသည်",
 "A document is already attached. Choose a file only to replace it.": "စာရွက်စာတမ်း တစ်ခု ပူးတွဲပြီးဖြစ်သည်။ အစားထိုးလိုမှသာ ဖိုင်ကို ရွေးပါ။",
 "A face photo is required as attendance proof.": "တက်ရောက်မှု သက်သေအဖြစ် မျက်နှာဓာတ်ပုံ လိုအပ်သည်။",
 "a file (PDF, Excel or CSV)": "ဖိုင်တစ်ခု (PDF, Excel သို့မဟုတ် CSV)",
 "A multi-day event can have at most {0} days.": "ရက်များစွာပါသော ပွဲတစ်ခုတွင် အများဆုံး {0} ရက်သာ ရှိနိုင်သည်။",
 "A part payment is fine: you can request less than the balance and request the rest later. Approval does not mark anything as paid.": "တစ်စိတ်တစ်ပိုင်း ပေးချေခြင်း ရပါသည်။ ကျန်ငွေထက် လျော့၍ တောင်းဆိုပြီး ကျန်သည်ကို နောက်မှ တောင်းဆိုနိုင်ပါသည်။ အတည်ပြုခြင်းဖြင့် ပေးချေပြီးဟု မှတ်သားမည် မဟုတ်ပါ။",
 "A payment is already being processed for this record.": "ဤမှတ်တမ်းအတွက် ငွေပေးချေမှုကို ဆောင်ရွက်နေပြီ ဖြစ်သည်။",
 "A payment with the same transaction reference, amount and date is already recorded. Check that this is not a duplicate entry.": "ငွေလွှဲကိုးကားနံပါတ်၊ ပမာဏနှင့် ရက်စွဲ တူညီသော ငွေပေးချေမှု မှတ်တမ်းတင်ပြီးသား ဖြစ်သည်။ ထပ်နေသော မှတ်တမ်း မဟုတ်ကြောင်း စစ်ဆေးပါ။",
 "A phone number or an email is needed.": "ဖုန်းနံပါတ် သို့မဟုတ် အီးမေးလ် လိုအပ်သည်။",
 "a photo or screenshot": "ဓာတ်ပုံ သို့မဟုတ် ဖန်သားပြင်ပုံ",
