 "A reason is required to correct attendance.": "တက်ရောက်မှုကို ပြင်ဆင်ရန် အကြောင်းရင်း လိုအပ်သည်။",
 "A reason is required.": "အကြောင်းရင်း လိုအပ်သည်။",
 "A recipe called \"{0}\" already exists for this company. Open that recipe instead of creating it again.": "ဤကုမ္ပဏီတွင် \"{0}\" အမည်ရှိ ချက်ပြုတ်နည်း ရှိပြီးဖြစ်သည်။ ထပ်မဖန်တီးဘဲ ထိုချက်ပြုတ်နည်းကို ဖွင့်ပါ။",
