 "A supplier invoice can be the cost of one event only, once. Paying it later is not a second cost.": "ပေးသွင်းသူ ငွေတောင်းခံလွှာတစ်ခုကို ပွဲတစ်ခု၏ ကုန်ကျစရိတ်အဖြစ် တစ်ကြိမ်သာ မှတ်နိုင်သည်။ နောက်မှ ပေးချေခြင်းသည် ဒုတိယကုန်ကျစရိတ် မဟုတ်ပါ။",
