 "You are about {0} m from the event location. You must be within {1} m to clock out. If you are at the event, tell the office so the location can be corrected.": "သင်သည် ပွဲတည်နေရာမှ ခန့်မှန်း {0} မီတာ အကွာတွင် ရှိသည်။ Clock out လုပ်ရန် {1} မီတာအတွင်း ရှိရမည်။ ပွဲတွင် ရှိနေပါက တည်နေရာ ပြင်ဆင်နိုင်ရန် ရုံးကို အသိပေးပါ။",
