 "You can only clock in or out as yourself. Ask an admin to link your login to your driver record.": "သင့်ကိုယ်ပိုင်အတွက်သာ အလုပ်ဝင်/ထွက်ချိန်မှတ်နိုင်သည်။ သင့်ဝင်ရောက်အကောင့်ကို သင့်ယာဉ်မောင်းမှတ်တမ်းနှင့် ချိတ်ဆက်ရန် အက်ဒမင်ကို တောင်းဆိုပါ။",
 "You can only create tasks for yourself. Ask an admin to assign it to someone else.": "သင်သည် ကိုယ်တိုင်အတွက်သာ လုပ်ငန်း ဖန်တီးနိုင်သည်။ အခြားသူထံ တာဝန်ပေးရန် အက်ဒမင်ကို တောင်းဆိုပါ။",
 "You can only submit OT for your own staff record. Ask an admin to link your login to your name.": "သင့်ကိုယ်ပိုင်ဝန်ထမ်းမှတ်တမ်းအတွက်သာ OT တင်နိုင်သည်။ သင့်ဝင်ရောက်အကောင့်ကို သင့်အမည်နှင့် ချိတ်ဆက်ရန် အက်ဒမင်ကို တောင်းဆိုပါ။",
